const express = require('express');
const crypto = require('crypto');

const app = express();
app.use(express.json());

const HMAC_SECRET = process.env.HMAC_SECRET || crypto.randomBytes(32).toString('hex');
const REQUEST_WINDOW_MS = 300000; // 5 minutes

// Replay protection cache with TTL
class NonceCache {
  constructor(ttlMs) {
    this.cache = new Map();
    this.ttl = ttlMs;
    setInterval(() => this.cleanup(), ttlMs);
  }
  has(key) { 
    if (!this.cache.has(key)) return false;
    if (Date.now() - this.cache.get(key) > this.ttl) {
      this.cache.delete(key);
      return false;
    }
    return true;
  }
  add(key) { this.cache.set(key, Date.now()); }
  cleanup() {
    const now = Date.now();
    for (const [k, v] of this.cache) {
      if (now - v > this.ttl) this.cache.delete(k);
    }
  }
}

const replayCache = new NonceCache(REQUEST_WINDOW_MS);

function isValidHex(str) {
  return typeof str === 'string' && str.length > 0 && str.length % 2 === 0 && /^[0-9a-fA-F]+$/.test(str);
}

function verifyTimestamp(timestamp) {
  const ts = parseInt(timestamp, 10);
  if (isNaN(ts)) return false;
  const diff = Math.abs(Date.now() - ts);
  return diff <= REQUEST_WINDOW_MS;
}

function computeHmac(timestamp, nonce, body) {
  const message = `${timestamp}.${nonce}.${JSON.stringify(body)}`;
  return crypto.createHmac('sha256', HMAC_SECRET).update(message).digest('hex');
}

function verifySignature(req, res, next) {
  const signature = req.headers['x-signature'];
  const timestamp = req.headers['x-timestamp'];
  const nonce = req.headers['x-nonce'];

  if (!signature || !timestamp || !nonce) {
    return res.status(401).json({ error: 'Missing authentication headers' });
  }

  if (!isValidHex(signature)) {
    return res.status(401).json({ error: 'Invalid signature format' });
  }

  if (!verifyTimestamp(timestamp)) {
    return res.status(401).json({ error: 'Request expired' });
  }

  // Replay protection - always enforced unconditionally
  // Normalize signature to lowercase for consistent cache lookups
  const normalizedSig = signature.toLowerCase();
  const cacheKey = `${nonce}:${normalizedSig}`;
  if (replayCache.has(cacheKey)) {
    return res.status(409).json({ error: 'Replay detected' });
  }

  const expectedHmac = computeHmac(timestamp, nonce, req.body);

  // Convert both to buffers for constant-time comparison
  const sigBuffer = Buffer.from(signature, 'hex');
  const expectedBuffer = Buffer.from(expectedHmac, 'hex');

  if (sigBuffer.length !== expectedBuffer.length) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  if (!crypto.timingSafeEqual(sigBuffer, expectedBuffer)) {
    return res.status(401).json({ error: 'Invalid signature' });
  }

  // Record after successful verification using normalized key
  replayCache.add(cacheKey);

  next();
}

app.post('/api/transfer', verifySignature, (req, res) => {
  const { to, amount } = req.body;
  // Process transfer
  res.json({ success: true, to, amount, txId: crypto.randomUUID() });
});

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

app.listen(3000);
module.exports = app;
